// План specs/admin-access.md, 2.1 (кейс AA-05). Admin «Kirill · Admin». Только чтение: внутри консоли ничего не нажимать. @prod-safe
import { test, expect } from '@playwright/test';
import { setLanguage } from '../admin-plans/plans-helpers';
import { sectionTab, waitForMenu } from './access-helpers';

test.use({ storageState: '../auth/admin.json' });

test.describe('Support Console — admin как раньше (#09773471)', () => {
  test('Admin opens Support Console from the menu and directly, with Bug Report, Support Task and Chat tabs #09773471 @desktop @prod-safe', async ({ page }) => {
    await setLanguage(page, 'en');

    // Шаг 1: в меню есть оба служебных пункта
    await page.goto('/dashboard');
    await waitForMenu(page);
    await expect(page.getByRole('link', { name: 'Admin Panel' })).toBeVisible();
    const menuItem = page.getByRole('link', { name: 'Support Console' });
    await expect(menuItem).toBeVisible();

    // Шаг 2: из меню
    await menuItem.click();
    await expect(page).toHaveURL(/\/supportinbox(\?|#|$)/);
    for (const t of ['Bug Report', 'Support Task', 'Chat']) await expect(sectionTab(page, t).first()).toBeVisible();
    await expect(page.getByText('Access Denied')).toHaveCount(0);

    // Шаг 3: напрямую — редиректа нет
    await page.goto('/supportinbox');
    for (const t of ['Bug Report', 'Support Task', 'Chat']) await expect(sectionTab(page, t).first()).toBeVisible();
    await expect(page).toHaveURL(/\/supportinbox(\?|#|$)/);
    await expect(page.getByText('Access Denied')).toHaveCount(0);
  });
});
